function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',4500)}
function setTheme(){document.body.classList.toggle('light',state.theme==='light')}
function button(text,action,cls=''){return `<button class="${cls}" data-action="${action}">${text}</button>`}
const dbP=new Promise((resolve,reject)=>{const q=indexedDB.open('replay-studio-data',1);q.onupgradeneeded=()=>q.result.createObjectStore('bars');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)});
async function dbGet(id){const db=await dbP;return new Promise((r,j)=>{const q=db.transaction('bars').objectStore('bars').get(id);q.onsuccess=()=>r(q.result);q.onerror=()=>j(q.error)})}
async function dbPut(id,data){const db=await dbP;return new Promise((r,j)=>{const t=db.transaction('bars','readwrite');t.objectStore('bars').put(data,id);t.oncomplete=r;t.onerror=()=>j(t.error)})}
async function dbPutMany(entries){const db=await dbP;return new Promise((resolve,reject)=>{const tx=db.transaction('bars','readwrite');for(const [id,data] of entries)tx.objectStore('bars').put(data,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Unable to save historical prices.'))})}
function sessionTradeRecords(s){return [...(s.trades||[]).map(t=>({trade:t,runNumber:s.currentRunNumber||1,archived:false})),...(s.replayRuns||[]).flatMap(r=>(r.trades||[]).map(t=>({trade:t,runNumber:r.number,archived:true})))]}
function allTrades(){return state.sessions.filter(s=>!s.deleted).flatMap(s=>sessionTradeRecords(s).map(({trade:t,runNumber,archived})=>({...t,session:s.name+' · Run '+runNumber,sessionId:s.id,sym:s.symbol,archived,reason:archived&&t.exit===undefined?'Archived open':t.reason})))}
function closed(){return allTrades().filter(t=>t.exit!==undefined).sort((a,b)=>(a.exitTime??a.t)-(b.exitTime??b.t))}
function priceMoveValue(sym,entry,exit){return (exit-entry)*(sym==='USDJPY'?100000/exit:symbols[sym].mult)}
function positionMargin(sym,entry,quantity,leverage){return quantity*(sym==='USDJPY'?100000:entry*symbols[sym].mult)/leverage}
function marketExitPrice(trade,reference){return reference+(trade.executionModel==='mid-spread-v2'?(trade.side==='Buy'?-1:1)*(trade.spreadPrice||0)/2:0)}
function pnl(t,sym,price){return priceMoveValue(sym,t.entry,t.exit===undefined&&price!==undefined?marketExitPrice(t,price):price??t.exit)*(t.side==='Buy'?1:-1)*t.qty-(t.commission||0)}
function total(s){return s.balance+(s.trades||[]).filter(t=>t.exit!==undefined).reduce((v,t)=>v+pnl(t,s.symbol),0)}
function statsHtml(){const t=closed(),net=t.reduce((v,x)=>v+pnl(x,x.sym),0),wins=t.filter(x=>pnl(x,x.sym)>0).length;return `<div class="stats"><div class="stat"><span class="muted">Net P&L</span><strong class="${net>=0?'green':'red'}">${money(net)}</strong></div><div class="stat"><span class="muted">Win rate</span><strong>${t.length?(100*wins/t.length).toFixed(1):'0.0'}%</strong></div><div class="stat"><span class="muted">Total trades</span><strong>${allTrades().length}</strong></div><div class="stat"><span class="muted">Sessions</span><strong>${state.sessions.filter(s=>!s.deleted).length}</strong></div></div>`}
function spark(){return `<svg viewBox="0 0 300 130" fill="none"><path d="M0 110H300M0 70H300M0 30H300" stroke="#263343"/><path d="M0 105L18 99L30 110L48 76L60 85L79 65L94 80L111 48L125 69L144 59L160 66L182 29L200 40L217 20L233 43L250 36L267 12L285 24L300 5" stroke="#5a92ff" stroke-width="2"/><path d="M0 105L18 99L30 110L48 76L60 85L79 65L94 80L111 48L125 69L144 59L160 66L182 29L200 40L217 20L233 43L250 36L267 12L285 24L300 5V130H0Z" fill="#3478ee" opacity=".09"/></svg>`}
function dashboard(){return `<div class="hero"><h2>Welcome to Testing</h2><p>Choose how you want to test your strategy — by building data, or testing under prop firm rules</p></div><div class="choices"><button class="choice" data-action="new"><span class="icon">↗</span><span><strong>Backtesting session</strong><small>Build data to refine your strategy</small></span><span class="grow"></span>↗</button><button class="choice" data-action="prop"><span class="icon">♜</span><span><strong>Prop firm session</strong><small>Test your strategy against prop firm rules</small></span><span class="grow"></span>↗</button></div>${state.sessions.some(s=>!s.deleted)?statsHtml()+`<div class="row between"><h3>Recent sessions</h3>${button('View all →','sessions','ghost')}</div>`+sessionTable(true):''}<h3>Here's how to get started</h3><div class="learn">${[['Create a session','Choose an asset, starting date and account balance.','new','New session +'],['Place a trade','Replay the market and practice your execution.','guide','Buy / Sell'],['Journal your trades','Save your notes and review every decision.','trades','Save & Journal']].map((x,i)=>`<div class="card"><div class="mini">${spark()}<span class="float">${x[3]}</span></div><div class="cardpad"><h3>${x[0]}</h3><p>${x[1]}</p><button class="ghost small" data-action="${x[2]}">Get started →</button></div></div>`).join('')}</div>`}
function sessionProgress(s){if(!s.replayStarted&&!s.trades.length)return 'Not started';if(!Number.isFinite(s.length)||s.length<=0)return '—';return Math.round(Math.max(0,Math.min(1,(Number.isFinite(s.cursor)?s.cursor:1)/s.length))*100)+'%'}
function sessionTable(recent=false){const list=state.sessions.filter(s=>!s.deleted).filter(s=>!$('#search')||s.name.toLowerCase().includes($('#search').value.toLowerCase()));if(!list.length)return `<div class="card empty"><h3>No sessions yet</h3><p>Start with historical EURUSD prices or import your own CSV.</p>${button('+ New session','new','primary')}</div>`;return `<div class="tablewrap"><table><thead><tr><th>SESSION NAME</th><th>ASSET</th><th>DATA</th><th>BALANCE</th><th>TRADES</th><th>PROGRESS</th><th></th></tr></thead><tbody>${list.slice(0,recent?3:1000).map(s=>`<tr><td><strong>${esc(s.name)}</strong><div class="muted small">${esc(s.type)} · ${esc(s.strategy||'No strategy')}</div></td><td>${s.symbol}</td><td><span class="${s.demo?'tagdemo':'pill'}">${s.demo?'LEGACY DEMO':s.sourceName?'HISTORICAL':'IMPORTED'}</span></td><td>${money(total(s))}</td><td>${sessionTradeRecords(s).length}</td><td>${sessionProgress(s)}</td><td><button data-open="${esc(s.id)}" class="primary">Resume ↗</button> <button data-delete="${esc(s.id)}" title="Move session to trash" aria-label="Delete ${esc(s.name)}">⌫</button></td></tr>`).join('')}</tbody></table></div>`}
function tradesTable(ts=allTrades()){return !ts.length?'<div class="empty">No trades yet. Place an order in a replay session to get started.</div>':`<div class="tablewrap"><table><thead><tr><th>ASSET</th><th>SIDE</th><th>ENTRY</th><th>EXIT</th><th>SIZE</th><th>P&L</th><th>STATUS</th><th>JOURNAL</th></tr></thead><tbody>${ts.map(t=>`<tr><td>${t.sym||active?.symbol}<div class="muted">${esc(t.session||'')}</div></td><td class="${t.side==='Buy'?'green':'red'}">${t.side}</td><td>${t.entry.toFixed(symbols[t.sym||active.symbol].dec)}</td><td>${t.exit===undefined?'—':t.exit.toFixed(symbols[t.sym||active.symbol].dec)}</td><td>${t.qty}</td><td class="${t.exit===undefined?'':pnl(t,t.sym||active.symbol)>=0?'green':'red'}">${t.exit===undefined?'Open':money(pnl(t,t.sym||active.symbol))}</td><td>${esc(t.reason||'Open')}${t.execution?.ambiguous?'<div class="muted small">Both touched · SL first</div>':t.execution?.gap?'<div class="muted small">Opening gap</div>':''}</td><td><button data-journal="${esc(t.id)}" data-journal-session="${esc(t.sessionId||active?.id||'')}">✎ ${t.notes?'Edit':'Add notes'}</button>${active&&t.exit===undefined?` <button data-close="${esc(t.id)}">Close</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function analytics(){const t=closed(),profits=t.map(x=>pnl(x,x.sym)),gp=profits.filter(v=>v>0).reduce((a,b)=>a+b,0),gl=-profits.filter(v=>v<0).reduce((a,b)=>a+b,0);let peak=0,equity=0,dd=0,curve=[0];profits.forEach(p=>{equity+=p;peak=Math.max(peak,equity);dd=Math.max(dd,peak-equity);curve.push(equity)});const lo=Math.min(...curve,0),hi=Math.max(...curve,1),pts=curve.map((n,i)=>`${40+i/(Math.max(1,curve.length-1))*920},${200-(n-lo)/(hi-lo)*170}`).join(' ');return statsHtml()+`<div class="card cardpad"><h3>Equity curve</h3><p>Closed trades · all sessions</p><svg class="equity" viewBox="0 0 1000 230" preserveAspectRatio="none"><path d="M40 30H960M40 110H960M40 200H960" stroke="#28313c"/><polyline points="${pts}" fill="none" stroke="#4389ff" stroke-width="2.5"/></svg></div><div class="stats"><div class="stat">Profit factor<strong>${gl?(gp/gl).toFixed(2):gp?'∞':'—'}</strong></div><div class="stat">Max drawdown<strong>${money(dd)}</strong></div><div class="stat">Average trade<strong>${money(profits.length?equity/profits.length:0)}</strong></div><div class="stat">Best trade<strong>${money(profits.length?Math.max(...profits):0)}</strong></div></div>`}
function render(){setTheme();if(active)return renderChart();const tabs=['Dashboard','Sessions','Trades','Analytics'];app.innerHTML=`<header class="topbar"><span class="muted">☰</span><span class="brand">REPLAY <span>STUDIO</span></span><span class="grow"></span><span class="pill">Personal workspace</span>${button('☼','theme','ghost')} ${button('Help','guide','ghost')}</header><aside class="sidebar"><div class="profile"><div class="avatar">A</div><strong>Abbas</strong><div class="muted small">Your backtesting workspace</div></div>${[['Get Started','◈'],['Testing','⌁'],['Strategies','◎'],['Data Manager','▤']].map(x=>`<button class="nav ${section===x[0]?'active':''}" data-section="${x[0]}"><span>${x[1]}</span>${x[0]}</button>`).join('')}<button class="nav bottom" data-section="Settings">⚙ Settings & backups</button><span class="muted small">Replay Studio · v1.0</span></aside><main class="main"><div class="row between titlearea"><h1>${esc(section)}</h1><span class="pill">Practice. Review. Improve.</span></div>${section==='Testing'?`<nav class="tabs" role="tablist">${tabs.map((t,i)=>`<button role="tab" aria-selected="${page===t}" class="tab ${page===t?'active':''}" data-page="${t}">${['▦','▤','⇄','▥'][i]} &nbsp;${t}</button>`).join('')}</nav>${page==='Dashboard'?dashboard():page==='Sessions'?`<div class="toolbar"><input id="search" placeholder="Search sessions…" aria-label="Search sessions"><span class="grow"></span>${button('Trash','trash')}${button('+ New session','new','primary')}</div><div id="sessiontable">${sessionTable()}</div>`:page==='Trades'?`<div class="toolbar"><h3 class="grow">Trade journal</h3>${button('Export trades CSV','exporttrades')}</div>${tradesTable()}`:analytics()}`:section==='Data Manager'?dataPage():section==='Strategies'?strategyPage():section==='Settings'?settingsPage():helpPage()}</main>`;if($('#search'))$('#search').oninput=()=>$('#sessiontable').innerHTML=sessionTable();}
function dataPage(){return `<div class="card cardpad"><h2>Your historical data</h2><p>Import real OHLC data from MT4, MT5 or a CSV provider. Data stays in this browser. Sessions can contain one or two independent asset tracks. Import one-minute data for the widest range of chart intervals. No live connection.</p>${button('+ Import data & create session','import')}<p><a href="https://www.histdata.com/f-a-q/" target="_blank" rel="noopener">HistData downloads and format details</a></p><p>Supported: CSV / TSV; time, open, high, low, close, volume. MetaTrader date + time columns are supported. Timestamps without a zone are interpreted as UTC.</p></div><br>${sessionTable()}`}
