function attachCanvas(){$$('.chartcanvas').forEach((c,i)=>{let drag=null;c.onpointerdown=e=>{const g=geo[i];if(!g)return;const r=c.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,j=Math.round((x-15)/g.dx),b=g.vis[Math.max(0,Math.min(g.vis.length-1,j))],p=g.hi-(y-g.top)/(g.bot-g.top)*(g.hi-g.lo);if(tool==='start'){if(b)seek(b.index+1);tool='crosshair';$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));return}if(tool==='crosshair'){drag={x:e.clientX,offset:viewOffset};c.setPointerCapture(e.pointerId);return}if(tool==='erase')return;if(!b)return;const point={t:b.t,p};if(tool==='horizontal'){chartObjects.push({type:tool,panel:i,a:point});save();drawCharts()}else if(pending&&pending.panel===i){chartObjects.push({type:tool,panel:i,a:pending.point,b:point});pending=null;save();drawCharts()}else{pending={point,panel:i};toast('Click the second point to finish the drawing.')}};c.onpointermove=e=>{const g=geo[i];if(!g)return;const r=c.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(drag){viewOffset=Math.max(0,Math.min(g.data.length-1,drag.offset+Math.round((e.clientX-drag.x)/g.dx)));follow=false;$('#follow').textContent='Follow: Off'}let b=g.vis[Math.max(0,Math.min(g.vis.length-1,Math.round((x-15)/g.dx)))];cross={panel:i,x,y,t:b?.t};drawCharts()};c.onpointerup=()=>drag=null;c.onpointercancel=()=>drag=null;c.onpointerleave=()=>{cross=null;drawCharts()};c.onwheel=e=>{e.preventDefault();visibleBars=Math.max(25,Math.min(600,visibleBars+(e.deltaY>0?10:-10)));drawCharts()}})}
