document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.action&&actions[d.action]){if(!el.onclick)actions[d.action]();return}if(d.page){page=d.page;render()}if(d.section){section=d.section;render()}if(d.open)openSession(d.open);if(d.delete){state.sessions.find(s=>s.id===d.delete).deleted=true;save();render();toast('Session moved to trash. You can restore it.')}if(d.restoreSession){state.sessions.find(s=>s.id===d.restoreSession).deleted=false;save();modal.innerHTML='';render()}if(d.journal)journal(d.journal,d.journalSession);if(d.close){stop();closeTrade(active.trades.find(t=>t.id===d.close))}if(d.balance){$('#balance').value=d.balance;$$('[data-balance]').forEach(b=>b.classList.toggle('active',b===el))}if(d.type){draftType=d.type;$$('[data-type]').forEach(b=>b.classList.toggle('active',b===el))}if(d.tool){if(d.tool==='erase'){checkpoint();chartObjects.pop();save();drawCharts()}else{tool=d.tool;pending=null;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b===el))}}});
